import 'package:cephalopod/features/game/presentation/models/board_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'tutorial_step_ui.freezed.dart';

/// One page of How to play as the screen draws it: its [title], the
/// explanation in [body], and the example [board].
///
/// The title and body are text rather than meanings: they describe their
/// example, so they stay next to it (docs/adr/0015).
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
abstract class TutorialStepUi with _$TutorialStepUi {
  const factory TutorialStepUi({
    required String title,
    required String body,
    required BoardUi board,
  }) = _TutorialStepUi;
}
